class Solution:
    def longestSubstring(self, s):
        vowels = set('aeiouAEIOU')
        n = len(s)
        prefix_sums = [0] * (n + 1)
        for i in range(n):
            val = -2 if s[i] in vowels else 1
            prefix_sums[i + 1] = prefix_sums[i] + val

        unique_sorted = sorted(list(set(prefix_sums)))
        rank = {val: i + 1 for i, val in enumerate(unique_sorted)}
        max_rank = len(unique_sorted)
        bit = [float('inf')] * (max_rank + 1)

        def update(idx, val):
            while idx <= max_rank:
                bit[idx] = min(bit[idx], val)
                idx += idx & (-idx)

        def query(idx):
            res = float('inf')
            while idx > 0:
                res = min(res, bit[idx])
                idx -= idx & (-idx)
            return res

        max_len, start_idx = 0, -1
        for i in range(n + 1):
            min_idx = query(rank[prefix_sums[i]])
            if min_idx != float('inf'):
                if i - min_idx > max_len:
                    max_len = i - min_idx
                    start_idx = min_idx
            update(rank[prefix_sums[i]], i)

        return "-1" if max_len == 0 else s[start_idx:start_idx + max_len]
